import React, { useState } from 'react';
import { Map, MapPin, ChevronRight, ChevronLeft, Search, Box } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); 
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  const zoneData = [
    {
      id: 'Z-1', name: 'NORTH_SECTOR', code: 'NS-ALPHA',
      areas: [
        { id: 'A-1', name: 'Hillside Drive', location: 'North Ridge', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-2', name: 'University Road', location: 'East Campus', code: 'URD-12', bins: ['BN-502', 'BN-503'] }
      ]
    },
    {
      id: 'Z-2', name: 'CENTRAL_HUB', code: 'CH-BRAVO',
      areas: [
        { id: 'A-3', name: 'Main Square', location: 'Downtown', code: 'MSQ-01', bins: ['BN-101', 'BN-102'] }
      ]
    }
  ];

  const displayData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full animate-slot flex flex-col gap-8 py-4">

      {/* HEADER & SEARCH */}
      <div className="flex justify-between items-center border-b-2 border-[#47510B]/10 pb-6">
        <div className="flex items-center gap-6">
          {viewLevel !== 'ZONES' && (
            <button onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')} className="text-[#47510B] hover:text-[#AB1717]">
              <ChevronLeft size={28} />
            </button>
          )}
          <h2 className="text-3xl font-black italic text-[#47510B] tracking-tighter uppercase">
            {viewLevel === 'ZONES' ? 'ZONES' : viewLevel === 'AREAS' ? selectedZone.name : selectedArea.name}
          </h2>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-2.5 text-[#47510B]/30" size={18} />
          <input 
            type="text" placeholder="SEARCH..." 
            className="bg-transparent border-b-2 border-[#47510B] py-2 pl-10 pr-4 text-xs font-black uppercase outline-none focus:border-[#AB1717] w-40 md:w-64 transition-all"
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* LEVEL 1: ZONES (Clean List) */}
      {viewLevel === 'ZONES' && (
        <div className="flex flex-col">
          {displayData.map(zone => (
            <div key={zone.id} onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
              className="group flex justify-between items-center py-6 border-b border-[#47510B]/10 cursor-pointer hover:px-4 transition-all hover:bg-[#CAD23C]/10">
              <div className="flex items-baseline gap-4">
                <span className="text-[#AB1717] font-mono text-xs font-black">{zone.code}</span>
                <h3 className="text-xl font-black text-[#47510B] tracking-tight">{zone.name}</h3>
              </div>
              <div className="flex items-center gap-8">
                <span className="text-[10px] font-black opacity-30 uppercase">{zone.areas.length} AREAS</span>
                <ChevronRight size={20} className="text-[#47510B] opacity-20 group-hover:opacity-100" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* LEVEL 2: AREAS (Minimal Table) */}
      {viewLevel === 'AREAS' && (
        <div className="flex flex-col">
          {displayData.map(area => (
            <div key={area.id} onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
              className="group flex flex-col md:flex-row md:items-center justify-between py-6 border-b border-[#47510B]/10 cursor-pointer hover:bg-[#FDFAD8] transition-all px-2">
              <div className="flex flex-col gap-1">
                <h4 className="text-lg font-black text-[#47510B] uppercase">{area.name}</h4>
                <div className="flex items-center gap-2 opacity-40">
                  <MapPin size={12} />
                  <span className="text-[10px] font-bold uppercase">{area.location}</span>
                </div>
              </div>
              <div className="flex items-center justify-between md:justify-end gap-12 mt-4 md:mt-0">
                <span className="text-[10px] font-black text-[#AB1717] border border-[#AB1717] px-2 py-0.5">{area.code}</span>
                <div className="flex items-center gap-4">
                  <span className="text-xs font-black text-[#47510B]">{area.bins.length} BINS</span>
                  <ChevronRight size={20} className="opacity-20 group-hover:opacity-100" />
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* LEVEL 3: BINS (Clean Grid) */}
      {viewLevel === 'BINS' && (
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-6 animate-slot">
          {selectedArea.bins.map(binId => (
            <div key={binId} className="flex flex-col items-center gap-3 p-6 border-2 border-[#47510B]/5 hover:border-[#AB1717] transition-all group">
              <Box size={24} className="text-[#47510B]/20 group-hover:text-[#AB1717]" />
              <span className="text-xs font-black text-[#47510B] font-mono">{binId}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AreasZonesTab;
